def parse_go(
    file_path: Path,
    module_path: str,
    source_text: str,
) -> list[Chunk]:
    """Parses Go files and extracts semantic chunks."""
    lang_name = "go"
    lang = get_language(lang_name)
    parser = get_parser(lang_name)

    source_bytes = bytes(source_text, "utf-8")
    tree = parser.parse(source_bytes)

    query = lang.query(GO_QUERY)
    captures = query.captures(tree.root_node)

    chunks: list[Chunk] = []

    for node, capture_name in captures:
        if capture_name == "class":
            chunk_type = "class"
        elif capture_name == "method":
            chunk_type = "method"
        else:
            chunk_type = "function"

        symbol = f"anonymous_{chunk_type}"

        if chunk_type == "class":
            type_spec = node.child_by_field_name("name") or node.named_child(0)
            if type_spec:
                name_node = type_spec.child_by_field_name("name")
                if name_node:
                    symbol = source_bytes[name_node.start_byte : name_node.end_byte].decode("utf-8")
        else:
            name_node = node.child_by_field_name("name")
            if name_node:
                symbol = source_bytes[name_node.start_byte : name_node.end_byte].decode("utf-8")

        # Если это метод Go, вытаскиваем тип ресивера (получателя) из параметров: func (r *MyStruct) Method()
        if chunk_type == "method":
            receiver_node = node.child_by_field_name("receiver")
            if receiver_node:
                struct_name = None
                for child in receiver_node.children:
                    if child.type == "parameter_declaration":
                        type_node = child.child_by_field_name("type")
                        if type_node:
                            if type_node.type == "pointer_type":
                                type_node = type_node.named_child(0)
                            if type_node:
                                struct_name = source_bytes[type_node.start_byte : type_node.end_byte].decode("utf-8")
                if struct_name:
                    symbol = f"{struct_name}.{symbol}"

        start_line = node.start_point[0] + 1
        end_line = node.end_point[0] + 1
        code = source_bytes[node.start_byte : node.end_byte].decode("utf-8")

        docstring = None
        prev_sibling = node.prev_sibling
        if prev_sibling and prev_sibling.type in ("comment", "line_comment"):
            docstring = source_bytes[prev_sibling.start_byte : prev_sibling.end_byte].decode("utf-8")

        chunk_id = f"{module_path}:{symbol}:{start_line}"
        chunks.append(
            Chunk(
                chunk_id=chunk_id,
                path=module_path,
                language=lang_name,
                symbol=symbol,
                chunk_type=chunk_type,
                start_line=start_line,
                end_line=end_line,
                code=code,
                docstring=docstring,
            )
        )

    return chunks

def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
    if self.class_stack:
        symbol = f"{self.class_stack[-1]}.{node.name}"
        chunk_type = "method"
    else:
        symbol = node.name
        chunk_type = "function"

    self._append_chunk(node=node, symbol=symbol, chunk_type=chunk_type)
    self.generic_visit(node)

def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
    if self.class_stack:
        symbol = f"{self.class_stack[-1]}.{node.name}"
        chunk_type = "method"
    else:
        symbol = node.name
        chunk_type = "function"

    self._append_chunk(node=node, symbol=symbol, chunk_type=chunk_type)
    self.generic_visit(node)

def get_supported_extensions():
    """Returns a view of all supported file extensions."""
    return PARSERS_MAP.keys()

def collect_chunks_for_file(file_path: Path, source_root: Path, project_prefix: str) -> list[Chunk]:
    """Reads a file and routes it to the correct parser based on its extension."""
    ext = file_path.suffix.lower()
    if ext not in PARSERS_MAP:
        return []

    source_text = file_path.read_text(encoding="utf-8")
    module_path = chunker.utils.normalize_module_path(file_path, source_root, project_prefix)

    parse_function = PARSERS_MAP[ext]
    return parse_function(file_path, module_path, source_text)

def normalize_module_path(file_path: Path, source_root: Path, project_prefix: str) -> str:
    relative = file_path.relative_to(source_root)
    if project_prefix == source_root.name or not project_prefix:
        return relative.as_posix()
    return f"{project_prefix}/{relative.as_posix()}"

def write_jsonl(chunks: list[Chunk], output_path: Path) -> None:
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with output_path.open("w", encoding="utf-8") as f:
        for chunk in chunks:
            f.write(json.dumps(chunk.to_dict(), ensure_ascii=False) + "\n")

def iter_files(source_root: Path, supported_extensions: Iterable[str]) -> Iterable[Path]:
    for file_path in source_root.rglob("*"):
        if file_path.is_file() and "__pycache__" not in file_path.parts:
            if file_path.suffix.lower() in supported_extensions:
                yield file_path

def get_embedding(text: str, model: SentenceTransformer) -> list:
    """Generates a normalized embedding vector for a single text string."""
    embedding = model.encode(text, normalize_embeddings=True)
    return embedding.tolist()

def get_embeddings(texts: list[str], model: SentenceTransformer) -> list[list[float]]:
    """Generates embedding vectors for a list of text strings (batch processing)."""
    embeddings = model.encode(texts, normalize_embeddings=True)
    return embeddings.tolist()

def chunk_to_dict(chunk: Chunk) -> dict:
    """Safely converts a Chunk instance or dataclass into a standard dictionary."""
    if dataclasses.is_dataclass(chunk):
        return dataclasses.asdict(chunk)
    elif hasattr(chunk, "to_dict"):
        return chunk.to_dict()
    return vars(chunk)
